package com.aitu.lms.visitor;
import com.aitu.lms.domain.*; import java.util.*;
public final class JsonExportVisitor implements Visitor<String>{ public String visitFaculty(Faculty x){return object("faculty",x.name(),children(x.children()));} public String visitProgram(Program x){return object("program",x.name(),children(x.children()));} public String visitCourse(Course x){return "{\"type\":\"course\",\"name\":\""+esc(x.name())+"\",\"credits\":"+x.credits()+",\"children\":["+children(x.children())+"]}";} public String visitLecture(Lecture x){return leaf("lecture",x.name(),x.workload());} public String visitLab(Lab x){return leaf("lab",x.name(),x.workload());} public String visitExam(Exam x){return leaf("exam",x.name(),x.workload());} public String visitStudent(Student x){return "{\"type\":\"student\",\"id\":\""+esc(x.id())+"\",\"name\":\""+esc(x.name())+"\",\"gpa\":"+x.gpa()+"}";} private String children(List<Element> c){var r=new ArrayList<String>();for(Element e:c)r.add(e.accept(this));return String.join(",",r);} private String object(String t,String n,String c){return "{\"type\":\""+t+"\",\"name\":\""+esc(n)+"\",\"children\":["+c+"]}";} private String leaf(String t,String n,int w){return "{\"type\":\""+t+"\",\"name\":\""+esc(n)+"\",\"workload\":"+w+"}";} private String esc(String s){return s.replace("\\","\\\\").replace("\"","\\\"");} }
